const S = 'C:/Users/user/AppData/Local/Temp/claude/C--Users-user-AppData-Local-Temp-skill-eval-TWpISy/4ade16d0-692d-4492-b201-d4ec0182c03b/scratchpad';

async function load(entry, outfile) {
  await build({ entryPoints: [entry], bundle: true, format: 'esm', platform: 'node', outfile, logLevel: 'silent' });
  return import('file:///' + outfile);
}

const orig = await load(root + '/src/module.ts', S + '/orig.mjs');
const next = await load(root + '/out/module.ts', S + '/new.mjs');

const names = ['lee', 'kim', 'park', 'choi', 'jung'];
const rnd = (n) => Math.floor(Math.random() * n);
const rows = (len) => Array.from({ length: len }, () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) }));
const sorted = (len) => Array.from({ length: len }, () => -5 + rnd(26)).sort((a, b) => a - b);

// Example inputs from the task
const exById = [
  [{ id: 4, name: 'lee', age: 34 }, { id: 4, name: 'jung', age: 55 }, { id: 3, name: 'park', age: 51 }, { id: 1, name: 'lee', age: 44 }, { id: 3, name: 'kim', age: 57 }],
  [{ id: 5, name: 'jung', age: 20 }, { id: 4, name: 'lee', age: 41 }],
];
for (const r of exById) {
  assert.deepEqual(next.byId(r), orig.byId(r));
  assert.equal(next.totalAge(r), orig.totalAge(r));
}
for (const v of [[1, 4, 7, 15], [-4, 5, 9]]) {
  assert.deepEqual(next.dedupeSorted(v), orig.dedupeSorted(v));
}

// Random inputs in range
for (let i = 0; i < 5000; i++) {
  const r = rows(rnd(13));
  assert.deepEqual(next.byId(r), orig.byId(r));
  assert.equal(next.totalAge(r), orig.totalAge(r));
  const v = sorted(rnd(21));
  assert.deepEqual(next.dedupeSorted(v), orig.dedupeSorted(v));
}

// Edge cases
assert.deepEqual(next.byId([]), orig.byId([]));
assert.equal(next.totalAge([]), orig.totalAge([]));
assert.deepEqual(next.dedupeSorted([]), orig.dedupeSorted([]));
